from pathlib import Path
import json, collections, html
from needs import needs, identities

OUT=Path(__file__).resolve().parent
PROJECT=OUT.parents[1]
load=lambda name:json.loads((OUT/name).read_text(encoding='utf-8'))
inventory=load('inventory.json'); candidates=load('candidate_analysis.json'); summary=load('scan_summary.json');fleet=load('fleet_audio.json')
project=[r for r in inventory if r['root']==str(PROJECT/'Audio')]
source=[r for r in inventory if r not in project]
packs=collections.defaultdict(lambda:dict(count=0,bytes=0))
for r in source:
    key=r['pack'] if '\\' in r['relative'] else 'Loose source files'
    packs[key]['count']+=1;packs[key]['bytes']+=r['bytes']
families=collections.defaultdict(lambda:dict(count=0,referenced=0,unlinked=0,bytes=0))
for r in project:
    k=r['pack'] if '\\' in r['relative'] else 'Weather (root)'
    families[k]['count']+=1;families[k]['bytes']+=r['bytes']
    families[k]['referenced']+=r['reference_status'].startswith('Code/')
    families[k]['unlinked']+=r['reference_status'].startswith('No literal')
data=dict(needs=needs,candidates=candidates,identities=identities,fleet=fleet,summary=summary,
    families=dict(families),project=project,packs=dict(packs),
    library=[[r['path'],r['pack'],r.get('duration_s'),r.get('channels'),r.get('rate'),r['bytes']] for r in source])
(OUT/'needs.json').write_text(json.dumps(needs,indent=2),encoding='utf-8')
payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
